mapper.select:
SELECT EXISTS (
    SELECT 1 FROM user_identity
     WHERE identity_type = #{identityType}
       AND issuer = #{issuer}
       AND normalized_identifier = #{normalizedIdentifier}
)

mapper.insert:
INSERT INTO user_identity (
    id, user_id, identity_type, issuer, identifier, normalized_identifier, status
) VALUES (
    #{id}, #{userId}, 'USERNAME', 'local', #{normalizedUsername}, #{normalizedUsername}, 'ACTIVE'
)
ON CONFLICT (identity_type, issuer, normalized_identifier) DO NOTHING

INSERT INTO user_identity (
    id, user_id, identity_type, issuer, identifier, normalized_identifier, status, verified_at
) VALUES (
    #{id}, #{userId}, #{identityType}, #{issuer}, #{identifier}, #{normalizedIdentifier},
    #{status}, #{verifiedAt}
)
